const recordRegistrationCardPayment = `-- name: RecordRegistrationCardPayment :execrows

UPDATE event_registrations
SET payment_status = 'paid', paid_method = 'card', paid_on = ?1, paid_by = NULL,
    paid_at = ?2, payment_note = NULL, paid_amount_cents = ?3,
    paid_online_payment_id = ?4, updated_at = ?2
WHERE id = ?5 AND status = 'confirmed' AND payment_status IN ('due', 'announced')
`

type RecordRegistrationCardPaymentParams struct {
	PaidOn          sql.NullString
	Now             sql.NullString
	PaidAmountCents sql.NullInt64
	OnlinePaymentID sql.NullInt64
	ID              int64
}

// RecordRegistrationCardPayment is only called by the HelloAsso verification
// (research.md 008 R5, 012 R4).
func (q *Queries) RecordRegistrationCardPayment(ctx context.Context, arg RecordRegistrationCardPaymentParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, recordRegistrationCardPayment,
		arg.PaidOn,
		arg.Now,
		arg.PaidAmountCents,
		arg.OnlinePaymentID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

